[CmdletBinding()]param([string]$RepositoryRoot=(Resolve-Path(Join-Path $PSScriptRoot '..\..')).Path)
Set-StrictMode -Version 2.0;$ErrorActionPreference='Stop'
$files=@('Invoke-MSADPT.ps1','Modules\ADDnsSecurity\Invoke-MSADPTADDnsSecurity.ps1','Modules\Kerberos\Invoke-MSADPTKerberosSPNBaselineCollection-v0.1.2.ps1','Catalogs\module-registry.json','Policies\msadpt-policy.json')
foreach($rel in $files){$p=Join-Path $RepositoryRoot $rel;if(-not(Test-Path $p)){throw "Missing: $rel"};if([IO.Path]::GetExtension($p)-eq'.ps1'){$t=$null;$e=$null;[void][Management.Automation.Language.Parser]::ParseFile($p,[ref]$t,[ref]$e);if(@($e).Count){throw "$rel`: $(@($e|ForEach-Object{$_.Message})-join'; ')"}}else{$null=Get-Content $p -Raw|ConvertFrom-Json}}
$o=[IO.File]::ReadAllText((Join-Path $RepositoryRoot 'Invoke-MSADPT.ps1'));foreach($m in @("`$OrchestratorVersion = '1.4.0'",'Invoke-MSADPTKerberosSPNBaselineCollection-v0.1.2.ps1','ad-dns-effective-write-context.json','operational-errors=')){if(-not$o.Contains($m)){throw "Orchestrator contract missing: $m"}}
$d=[IO.File]::ReadAllText((Join-Path $RepositoryRoot 'Modules\ADDnsSecurity\Invoke-MSADPTADDnsSecurity.ps1'));foreach($m in @('EffectiveWriteAces','BroadPrincipalWriteDetected','AuthorizationBreadth','ad-dns-resolution-validation.json','CleanupVerified','NoSuchObject','Write-Output -NoEnumerate')){if(-not$d.Contains($m)){throw "DNS contract missing: $m"}}
[pscustomobject]@{Status='Passed';OrchestratorVersion='1.4.0';ADDnsModuleVersion='0.2.0';KerberosCollectorVersion='0.1.2';AuthorizationContract=$true;ResolutionContract=$true;CleanupContract=$true}
